strategy = {
    'module': 'authentication',
    'levels': {'unit': 60, 'integration': 30, 'e2e': 10},
    'out_of_scope': ['confirmation email delivery'],
}

total_days = 10
for level, pct in strategy['levels'].items():
    days = total_days * pct / 100
    print(f"{level}: {pct}% -> {days:.1f} days")

print('Out of scope:', ', '.join(strategy['out_of_scope']))
